<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';
use Omnigo\{Database,ShipmentSchema,ShipmentRepository,ShipmentWriter,ShipmentOrderMapper,ShipmentOrderIngestor,DeliveryMapper,DeliveryCipher};
function check(bool $ok,string $label):void{if(!$ok)throw new RuntimeException($label);}
$db=new Database(['dsn'=>'sqlite::memory:']);$db->pdo->exec(file_get_contents(__DIR__.'/schema.sqlite.sql'));ShipmentSchema::install($db);$db->run("INSERT INTO companies VALUES(1,'Örnek'),(2,'Diğer')");$db->run("INSERT INTO users VALUES(1,'test@example.test','Yönetici','x','admin',NULL)");
$cipher=DeliveryCipher::withKey(str_repeat('a',32));$ingest=new ShipmentOrderIngestor($db,$cipher);ShipmentOrderIngestor::activate($db,1,time()-600);ShipmentOrderIngestor::activate($db,2,time()-600);
$time=time()-60;$created=gmdate('c',$time);$n=['orderNumber'=>'100','customerfullName'=>'Müşteri','customerEmail'=>'a@test.invalid','shippingAddress'=>['fullName'=>'Alıcı','gsm'=>'05000000000','city'=>'Ankara','district'=>'Çankaya','address'=>'Teslimat adresi'],'billingAddress'=>['fullName'=>'Firma','address'=>'Fatura adresi','invoiceType'=>2,'taxHouse'=>'Örnek V.D.','taxId'=>'0012345678'],'packageHistories'=>[['status'=>'Created','createdDate'=>$time*1000]],'shipmentPackageStatus'=>'Picking','lines'=>[['orderLineId'=>9,'orderItemLineItemStatusName'=>'Picking','productName'=>'Ürün','quantity'=>2,'sellerInvoiceAmount'=>'123.45']]];
$rows=ShipmentOrderMapper::n11($n,DeliveryMapper::n11($n));$payload=$rows[0]['payload'];
check($payload['customerName']==='Müşteri'&&$payload['recipientName']==='Alıcı'&&$payload['invoiceName']==='Firma','Üç isim ayrımı');check($payload['invoiceCents']===12345&&$payload['quantity']===2,'Satır toplamı adetle tekrar çarpılmaz');check($payload['taxNumber']==='0012345678'&&str_contains($payload['invoiceAddress'],'V.D.: Örnek'),'Vergi alanları');
$save=fn($company,$provider,$rows)=>$db->transaction(fn()=>$ingest->ingest($company,$provider,$rows));$save(1,'n11',$rows);$save(1,'n11',$rows);$save(2,'n11',$rows);
check(count($db->all('SELECT * FROM shipment_entries'))===2,'Firma bazlı tekrar koruması');
$month=(new DateTimeImmutable($created))->setTimezone(new DateTimeZone('Europe/Istanbul'))->format('Y-m');$repo=new ShipmentRepository($db,$cipher);$scope=['all','n11',$month];$row=$repo->listing(1,$scope)['items'][0];
$draft=array_intersect_key($row,array_flip(['orderedAt','customerName','recipientName','phone','deliveryAddress','province','district','productName','quantity','invoiceName','invoiceAddress','recipientEmail','customerType','taxNumber']));$draft['orderedAt']=(new DateTimeImmutable($row['orderedAt']))->format('Y-m-d\TH:i:s');$draft['quantity']='2';$draft['invoiceAmount']='123,45';$draft['phone']='05559999999';
(new ShipmentWriter($db,$cipher))->update(['id'=>1,'role'=>'admin'],1,$row['id'],$scope,['record'=>$draft,'version'=>1]);
$rows[0]['payload']['phone']='05551111111';$rows[0]['payload']['recipientEmail']='guncel@test.invalid';$save(1,'n11',$rows);$updated=$repo->listing(1,$scope)['items'][0];check($updated['phone']==='05559999999'&&$updated['recipientEmail']==='guncel@test.invalid','Elle düzeltilen alan korunur, API alanı güncellenir');
$old=$rows;$old[0]['key']='older';$old[0]['payload']['orderedAt']=gmdate('c',time()-3600);$save(1,'n11',$old);$old[0]['payload']['orderedAt']=$created;$old[0]['payload']['province']='İstanbul';$save(1,'n11',$old);check($repo->listing(1,$scope)['total']===1,'Eski tarihler ve altı şehir dışı alınmaz');
$n['id']=999;$repacked=ShipmentOrderMapper::n11($n,DeliveryMapper::n11($n));check($repacked[0]['key']===$rows[0]['key'],'Paket değişmesi siparişi çoğaltmaz');
$p=['orderId'=>'a','orderDate'=>date('Y-m-d H:i',$time),'customerName'=>'Sipariş sahibi','shipmentAddress'=>['nameSurname'=>'Teslim alan','cityName'=>'Kayseri','displayAddressText'=>'Teslimat','phoneNumber'=>'05','customerEmail'=>'alici@test.invalid'],'billingAddress'=>['nameSurname'=>'Fatura kişisi','displayAddressText'=>'Fatura','invoiceType'=>2,'companyName'=>'Örnek AŞ','taxNumber'=>'0012345678','taxOffice'=>'Test'],'items'=>[['orderItemId'=>'line','quantity'=>3,'orderItemStatus'=>12,'product'=>['name'=>'Ürün'],'totalPrice'=>['currency'=>'TL','value'=>'300.25','valueInt'=>30025]]]];
$p['items'][0]+=['salePrice'=>['currency'=>'TL','value'=>'100.25'],'discountAmount'=>['currency'=>'TL','value'=>'0.50'],'discountDescription'=>'(Pazarama İndirimi - 0 TL)'];
$mapped=ShipmentOrderMapper::pazarama($p,DeliveryMapper::pazarama($p))[0]['payload'];check($mapped['recipientName']==='Teslim alan'&&$mapped['invoiceName']==='Örnek AŞ'&&$mapped['invoiceCents']===30025,'Pazarama alan ve tutar eşleşmesi');
$k=['order_id'=>'k1','order_state'=>'SHIPPING','created_date'=>$created,'customer'=>['firstname'=>'Sipariş','lastname'=>'Sahibi','shipping_address'=>['firstname'=>'Alıcı','lastname'=>'Adı','state'=>'Ankara'],'billing_address'=>['firstname'=>'Fatura','lastname'=>'Adı','street_1'=>'Fatura adresi']],'order_additional_fields'=>[['code'=>'is-corporate','value'=>'true'],['code'=>'invoice-title','value'=>'Fatura Şirketi'],['code'=>'tax-number','value'=>'0012345678'],['code'=>'tax-office','value'=>'Test VD']],'order_lines'=>[['order_line_id'=>'k1-1','order_line_state'=>'SHIPPING','price'=>250.50,'quantity'=>2,'product_title'=>'Ürün']]];
$mapped=ShipmentOrderMapper::koctas($k,DeliveryMapper::koctas($k))[0]['payload'];check($mapped['invoiceName']==='Fatura Şirketi'&&$mapped['customerType']==='Kurumsal'&&$mapped['invoiceCents']===25050&&$mapped['taxNumber']==='0012345678'&&str_contains($mapped['invoiceAddress'],'Test VD'),'Koçtaş ek alanlar, kimlik ayrımı ve tutar');
echo "Üç pazaryeri: alan ayrımı, fatura/vergi, tekilleştirme, tarih/şehir kapsamı ve elle düzenleme koruması geçti.\n";
